const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ----- Helper -----

function findTodo(title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('.view label');
    if (label && label.textContent === title) return items[i];
  }
  return null;
}

function findAllTodos() {
  return this.document.querySelectorAll('.todo-list li');
}

function findCheckbox(li) {
  return li.querySelector('.toggle');
}

function triggerEvent(el, eventName) {
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent(eventName, true, true);
  el.dispatchEvent(evt);
}

async function delay(ms) {
  return new Promise(function (r) { setTimeout(r, ms); });
}

// ----- Background steps -----

Given('the app is loaded', function () {
  // Already loaded by Before hook
});

Given('localStorage is empty', function () {
  this.localStorage.clear();
  this.window.location.hash = '';
  this.window.dispatchEvent(new this.window.Event('hashchange'));
  this.document.querySelector('.new-todo').value = '';
});

Given('a todo titled {string} exists', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  input.dispatchEvent(evt);
});

Given('a completed todo titled {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  input.dispatchEvent(evt);
  const li = findTodo.call(this, title);
  if (li) {
    findCheckbox(li).click();
  }
});

Given('{int} active todo(s) exist(s)', function (n) {
  for (let i = 1; i <= n; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = 'Todo ' + i;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
  }
});

Given('{int} active todos and {int} completed todo(s) exist', function (activeN, completedN) {
  for (let i = 1; i <= activeN; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = 'Active ' + i;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
  }
  for (let i = 1; i <= completedN; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = 'Completed ' + i;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
    const todos = findAllTodos.call(this);
    const last = todos[todos.length - 1];
    if (last) findCheckbox(last).click();
  }
});

Given('{int} todos exist, all completed', function (n) {
  for (let i = 1; i <= n; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = 'Todo ' + i;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
  }
  const cb = this.document.getElementById('toggle-all');
  if (cb) {
    cb.checked = true;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('change', true, true);
    cb.dispatchEvent(evt);
  }
});

Given('the new-todo input has focus', function () {
  const input = this.document.querySelector('.new-todo');
  input.focus();
});

Given('I am editing the todo {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  li.classList.add('editing');
  const edit = li.querySelector('.edit');
  edit.focus();
});

Given('{int} todos exist', function (n) {
  for (let i = 1; i <= n; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = 'Todo ' + i;
    const evt = this.document.createEvent('HTMLEvents');
    evt.initEvent('keyup', true, true);
    evt.keyCode = 13;
    input.dispatchEvent(evt);
  }
});

Given('I am viewing active todos', function () {
  this.navigate('#/active');
});

Given('I am viewing {string}', function (filter) {
  this.navigate(filter);
});

// ----- When steps -----

When('the app renders', function () {
  // App already renders on load
});

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  input.dispatchEvent(evt);
});

When('I create a todo titled {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  input.dispatchEvent(evt);
});

When('I click the toggle checkbox for {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const cb = findCheckbox(li);
  if (cb) cb.click();
});

When('I click the toggle checkbox for the {word} todo', function (ordinal) {
  const todos = findAllTodos.call(this);
  let idx;
  if (ordinal === 'first') idx = 0;
  else if (ordinal === 'second') idx = 1;
  else if (ordinal === 'third') idx = 2;
  else idx = parseInt(ordinal) - 1;
  if (todos[idx]) findCheckbox(todos[idx]).click();
});

When('I click the toggle-all checkbox', function () {
  const cb = this.document.getElementById('toggle-all');
  if (!cb) throw new Error('toggle-all checkbox not found');
  cb.click();
});

When('I click the {string} checkbox', function (id) {
  const el = this.document.getElementById(id);
  if (!el) throw new Error('Element not found: #' + id);
  el.click();
});

When('I click {string}', function (text) {
  const el = this.document.querySelector('.clear-completed');
  if (el) el.click();
});

When('I click the destroy button for {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const destroyBtn = li.querySelector('.destroy');
  if (!destroyBtn) throw new Error('Destroy button not found');
  destroyBtn.click();
});

When('I reveal the destroy button for {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const destroyBtn = li.querySelector('.destroy');
  if (!destroyBtn) throw new Error('Destroy button not found');
});

When('I toggle {string} as completed', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const cb = findCheckbox(li);
  if (cb) cb.click();
});

When('I double-click the label for {string}', function (title) {
  const li = findTodo.call(this, title);
  if (!li) throw new Error('Todo not found: ' + title);
  const label = li.querySelector('.view label');
  if (!label) throw new Error('Label not found');
  const evt = this.document.createEvent('MouseEvents');
  evt.initEvent('dblclick', true, true);
  label.dispatchEvent(evt);
});

When('I change the edit value to {string}', function (value) {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  if (!edit) throw new Error('No editing input found');
  edit.value = value;
});

When('I press Enter in the edit input', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  if (!edit) throw new Error('No editing input found');
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 13;
  edit.dispatchEvent(evt);
});

When('the edit input loses focus', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  if (!edit) throw new Error('No editing input found');
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('focusout', true, true);
  edit.dispatchEvent(evt);
});

When('I press Escape in the edit input', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  if (!edit) throw new Error('No editing input found');
  const evt = this.document.createEvent('HTMLEvents');
  evt.initEvent('keyup', true, true);
  evt.keyCode = 27;
  edit.dispatchEvent(evt);
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('the first visible todo is toggled as completed', function () {
  const todos = findAllTodos.call(this);
  if (todos.length > 0) {
    const cb = findCheckbox(todos[0]);
    if (cb) cb.click();
  }
});

When('I toggle the first visible todo as completed', function () {
  const todos = findAllTodos.call(this);
  if (todos.length > 0) {
    const cb = findCheckbox(todos[0]);
    if (cb) cb.click();
  }
});

// Reload: clear and re-init
When('the app is reloaded', function () {
  // Capture current localStorage before dispose — save BOTH todo data and filter
  const todoData = this.localStorage.getItem('todos-vanilla');
  const filterData = this.localStorage.getItem('todos-vanilla-filter');
  this.disposeApp();
  // Create a fresh window and restore persisted state before app.js eval
  // so the store reads the right data on init
  const fs = require('node:fs');
  const path = require('node:path');
  const { Window } = require('happy-dom');
  const ROOT = path.resolve(__dirname, '..', '..');
  const indexPath = path.join(ROOT, 'index.html');
  const appPath = path.join(ROOT, 'js', 'app.js');

  this.window = new Window({
    url: 'http://localhost/',
    settings: { disableJavaScriptFileLoading: true },
  });
  this.document = this.window.document;

  // Set ALL localStorage keys BEFORE eval so the store reads persisted data on init
  if (todoData !== null) {
    this.localStorage.setItem('todos-vanilla', todoData);
  }
  if (filterData !== null) {
    this.localStorage.setItem('todos-vanilla-filter', filterData);
  }

  this.document.write(fs.readFileSync(indexPath, 'utf8'));
  this.document.close();
  this.window.eval(fs.readFileSync(appPath, 'utf8'));
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
  this.window.dispatchEvent(new this.window.Event('load'));

  // Re-attach hash routing proxy
